'use strict';
const labPages=['laboratory','labSpecimens','labDocuments','labDocument','labReports','labMoisture','labMoldingSheet'];
const labOperator=()=>['laboratorista','auxiliar_laboratorio'].includes(state.user?.role);
const canLab=()=>['laboratorista','auxiliar_laboratorio','engenharia','gerente_engenharia','gerente_concresuper','programador'].includes(state.user.role);
const canManageLab=()=>['gerente_engenharia','gerente_concresuper','programador'].includes(state.user.role);
const labNum=(v,digits=2)=>v===null||v===undefined?'—':Number(v).toLocaleString('pt-BR',{maximumFractionDigits:digits});
const labMonth=()=>({from:monthRange(today())[0],to:monthRange(today())[1]});
const labNow=()=>new Date().toLocaleString('sv-SE',{timeZone:'America/Sao_Paulo'}).replace(' ','T').slice(0,16);
function labNavigation(){return navGroup('laboratory','Laboratório','lab',nav('labSpecimens','CPs e rompimentos','request')+(labOperator()?'':nav('labDocuments','Laudos por cliente','request')+nav('labReports','Relatórios e ocorrências','chart'))+nav('labMoisture','Umidade da areia','droplet'));}
function labRangeForm(id,f,extras=''){return `<form class="filters no-print" id="${id}"><label>De<input type="date" name="from" required value="${f.from}"></label><label>Até<input type="date" name="to" required value="${f.to}"></label>${extras}<button type="submit" class="primary">Consultar</button></form>`;}
function labTimeText(control){return control?.minutes===null||!control?'Sem referência/horários':labNum(control.minutes)+' min · '+({dentro:'dentro do limite informado',atingido:'limite informado atingido',ultrapassado:'limite informado ultrapassado'}[control.status]||'');}
function labSamplesPage(){const rows=state.labSamples||[],f=state.labSampleFilters||{...labMonth(),all:true};return heading('Laboratório','Rastreabilidade da moldagem aos resultados dos corpos de prova.',`<button id="lab-print-sheet">${icon('request')} Impressão de ficha</button><button id="lab-driver-new">${icon('users')} Cadastrar motorista</button>${canManageLab()?'<button id="lab-policy">Parâmetros do laboratório</button>':''}<button class="primary" id="lab-new-sample">${icon('plus')} Cadastrar amostra e CPs</button>`)+labRangeForm('lab-sample-filter',f,`<label class="lab-all-history"><input type="checkbox" name="all" ${f.all?'checked':''}>Todo o histórico</label>`)+`<div class="stats">${stat('Amostras',rows.length,'amostras',f.all?'Todo o histórico':'Por data de moldagem','lab')}${stat('CPs cadastrados',rows.reduce((sum,s)=>sum+s.cp_count,0),'CPs',f.all?'Todo o histórico':'No período de moldagem','request')}${stat('Resultados registrados',rows.reduce((sum,s)=>sum+(s.tested_count||0),0),'CPs','Sem os desconsiderados','check')}</div><section class="panel"><div class="panel-header"><h2>Amostras e moldagens</h2><small>Horários de Cascavel – PR</small></div><div class="table-wrap"><table><thead><tr><th>AMOSTRA / MOLDAGEM</th><th>CLIENTE / OBRA</th><th>NF / FCK</th><th>CB / MOTORISTA</th><th>CPs</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.label||s.code)}</strong>${s.set_type?`<small>Tipo ${esc(s.set_type)}</small>`:''}<small>${fmt(s.molded_on)}</small></td><td><strong>${esc(s.customer)}</strong><small>${esc(s.work_name)}</small><small>${esc(s.address)}</small></td><td>${esc(s.invoice_no)}<small>FCK ${labNum(s.fck_mpa)} MPa · Slump na obra ${esc(s.slump||'—')} · Moldagem ${esc(s.molding_slump||'—')}</small></td><td><strong>${esc(s.cb_code)}</strong><small>${esc(s.cb_plate)}</small><small>${esc(s.driver_name)}</small></td><td>${s.tested_count||0} ensaiados / ${s.cp_count} cadastrados</td><td><button data-lab-sample="${s.id}">Abrir amostra</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Nenhuma amostra neste período.</div></td></tr>'}</tbody></table></div></section>`;}
function labMoldingSheetPage(){const columns=[['Etiqueta',12],['NF',8],['Tipo',5],['Cliente / código / obra / endereço',25],['CB / placa / motorista',22],['Hora',6],['FCK (MPa)',7],['Laboratorista',15]];return heading('Ficha de moldagem','Tabela A4 em retrato para registrar vários conjuntos de corpos de prova.',`<button id="lab-sheet-back">Voltar</button><button id="print" class="primary">Imprimir / salvar PDF</button>`)+`<article class="lab-molding-sheet lab-sheet-batch">${reportHeader('Ficha de moldagem · Registro de amostras','Preenchimento manual · Cascavel – PR')}<div class="table-wrap"><table class="lab-sheet-batch-table"><colgroup>${columns.map(([,width])=>`<col width="${width}%">`).join('')}</colgroup><thead><tr>${columns.map(([name])=>`<th>${name}</th>`).join('')}</tr></thead><tbody>${Array.from({length:12},()=>`<tr class="lab-sheet-batch-entry">${columns.map(()=>'<td></td>').join('')}</tr><tr class="lab-sheet-batch-details"><td colspan="8"><div><span>Slump obra / mold.: _____ / _____</span><span>Temp. concreto / amb.: _____ / _____ °C</span><span>Água: ____ L</span><span>Estab.: ____ L</span><span>Venc.: N / S · ____ h</span></div><div class="lab-sheet-record-notes">Obs.: __________________________________________________________________________________________________________________</div></td></tr>`).join('')}</tbody></table></div></article>`;}

function labSpecimensTable(rows,actions=true){return `<div class="table-wrap"><table><thead><tr><th>CP / AMOSTRA</th><th>CLIENTE / OBRA / NF</th><th>MOLDAGEM / PREVISÃO</th><th>ROMPIMENTO / IDADE</th><th>FCK / ATINGIDA</th><th>COMPARAÇÃO</th>${actions?'<th class="no-print"></th>':''}</tr></thead><tbody>${rows.map(cp=>`<tr><td><strong>${esc(cp.number)}</strong><small>${esc(cp.sample_code)}</small>${cp.invalidated_at?'<span class="badge cancelado">Desconsiderado</span>':cp.overdue?'<span class="badge cancelado">Rompimento atrasado</span>':''}</td><td><strong>${esc(cp.customer)}</strong><small>${esc(cp.work_name)}</small><small>NF ${esc(cp.invoice_no)}</small><small>${esc(cp.cb_code)} · ${esc(cp.driver_name)}</small></td><td>${fmt(cp.molded_on)}<small>Previsto: ${fmt(cp.planned_on)}${cp.planned_at?' '+cp.planned_at.slice(11):''} · ${labCpAge(cp)}</small></td><td>${cp.broken_on?fmt(cp.broken_on):'Pendente'}<small>${cp.actual_age===null?'':cp.target_age===.5&&cp.actual_age_hours!==null?labNum(cp.actual_age_hours)+' horas de idade real':cp.actual_age+' dias de idade real'}</small></td><td>${labNum(cp.fck_mpa)} MPa<small><strong>${labNum(cp.strength_mpa)} MPa atingida</strong></small></td><td>${cp.strength_mpa===null?'—':labNum(cp.percent)+'% do FCK'}<small>${cp.difference===null?'':(cp.difference>0?'+':'')+labNum(cp.difference)+' MPa'}</small>${cp.actual_age===28&&!cp.invalidated_at?`<span class="badge ${cp.below?'cancelado':'concluido'}">${cp.below?'Abaixo do FCK aos 28 dias':'Atingiu a referência aos 28 dias'}</span>`:''}${cp.actual_age!==null&&(cp.target_age===.5?cp.actual_age_hours!==12:cp.actual_age!==cp.target_age)?'<small>Idade real diferente da programada</small>':''}</td>${actions?`<td class="no-print"><button data-lab-sample="${cp.sample_id}">Amostra</button>${!cp.invalidated_at?`<button data-lab-result="${cp.id}">${cp.broken_on?'Corrigir resultado':'Registrar rompimento'}</button><button data-lab-invalidate="${cp.id}">Desconsiderar</button>`:''}</td>`:''}</tr>`).join('')||`<tr><td colspan="${actions?7:6}"><div class="empty">Nenhum CP para os filtros.</div></td></tr>`}</tbody></table></div>`;}
const labCpAge=cp=>cp.target_age===.5?'12 horas':cp.target_age+' dias';
function labSetCards(rows,status=''){const groups=new Map();for(const cp of rows){if(!groups.has(cp.sample_id))groups.set(cp.sample_id,[]);groups.get(cp.sample_id).push(cp);}const match=cp=>status==='pending'?!cp.broken_on&&!cp.invalidated_at:status==='overdue'?cp.overdue:status==='invalid'?!!cp.invalidated_at:status==='tested'?!!cp.broken_on&&!cp.invalidated_at:true;return `<div class="lab-set-cards">${[...groups.values()].filter(cps=>status==='complete'?cps.every(cp=>cp.broken_on&&!cp.invalidated_at):cps.some(match)).map(cps=>{const s=cps[0],complete=cps.every(cp=>cp.broken_on&&!cp.invalidated_at),overdue=cps.some(cp=>cp.overdue);return `<details class="lab-set-card ${complete?'is-complete':overdue?'is-overdue':''}" data-lab-set="${s.sample_id}"><summary><div class="lab-set-header"><strong>${esc(s.label||s.sample_code)}</strong><span>${s.set_type?'Tipo '+esc(s.set_type):'Registro anterior'} · ${cps.length} CPs</span><button type="button" class="lab-deviation-button" data-lab-deviation="${s.sample_id}">${icon('chart')}Desvio padrão</button><span class="badge ${complete?'concluido':overdue?'cancelado':'pendente'}">${complete?'Completo':overdue?'Rompimento atrasado':'Em acompanhamento'}</span></div><div class="lab-set-info"><strong>${esc(s.work_name)}</strong><span>${esc(s.customer)}</span><span>NF ${esc(s.invoice_no)} · ${esc(s.cb_code)}</span><span>Moldagem: ${fmt(s.molded_on)}${s.molded_time?' às '+s.molded_time:''}</span></div><div class="lab-set-dates">${[.5,7,28,63,...cps.map(cp=>cp.target_age).filter(age=>![.5,7,28,63].includes(age))].filter((age,i,ages)=>ages.indexOf(age)===i).map(age=>{const items=cps.filter(cp=>cp.target_age===age);if(!items.length)return '';const pending=items.filter(cp=>!cp.broken_on&&!cp.invalidated_at),late=pending.some(cp=>cp.overdue),due=pending.some(cp=>cp.due_today),done=items.filter(cp=>cp.broken_on&&!cp.invalidated_at).length;return `<div><strong>${age===.5?'12 horas':age+' dias'}</strong><span>${late||due?`<i class="lab-due-dot ${late?'late':'today'}" aria-label="${late?'Atrasado':'Rompimento hoje'}" title="${late?'Atrasado':'Rompimento hoje'}"></i>`:''}${fmt(items[0].planned_on)}${items[0].planned_at?' · '+items[0].planned_at.slice(11):''}</span><small>${done}/${items.length} rompidos${items.some(cp=>cp.invalidated_at)?' · CP desconsiderado':''}</small>${[...new Set(items.filter(cp=>cp.broken_on).map(cp=>cp.broken_on+(cp.broken_time?' '+cp.broken_time:'')))].map(date=>`<small>Realizado: ${fmt(date.slice(0,10))}${date.slice(10)}</small>`).join('')}</div>`;}).join('')}</div><small class="lab-set-toggle">Clique para ver os resultados e registrar rompimentos</small></summary><div class="lab-set-results"><h3>Resultados individuais · ${esc(s.label||s.sample_code)}</h3>${labSpecimensTable(cps)}</div></details>`;}).join('')||'<div class="empty">Nenhum conjunto para os filtros selecionados.</div>'}</div>`;}
function labSpecimensPage(){const f=state.labSpecimenFilters||{...labMonth(),basis:'planned'},rows=state.labSpecimens||[];return heading('CPs e rompimentos','Conjuntos por etiqueta, prazos de rompimento e resultados individuais.',`<button id="lab-new-sample" class="primary">Cadastrar amostra e CPs</button>`)+labRangeForm('lab-specimen-filter',f,`<label>Referência<select name="basis">${[['planned','Data prevista de rompimento'],['molded','Data de moldagem'],['broken','Data de rompimento realizado']].map(([v,n])=>`<option value="${v}" ${f.basis===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Situação<select name="status">${[['','Todos'],['pending','Pendentes'],['overdue','Atrasados'],['tested','Com resultados'],['complete','Completos'],['invalid','Desconsiderados']].map(([v,n])=>`<option value="${v}" ${f.status===v?'selected':''}>${n}</option>`).join('')}</select></label>`)+labSetCards(rows,f.status);}
function labDeviationChart(groups){const series=groups.filter(g=>g.specimens?.length);if(!series.length)return '';const colors=['#6f9e82','#7394b0','#baa16d','#9c8ab0','#9b8585'],values=series.flatMap(g=>g.specimens.map(cp=>cp.strength_mpa)),low=Math.min(...values),high=Math.max(...values),pad=Math.max(1,(high-low)*.12),min=Math.max(0,Math.floor(low-pad)),max=Math.ceil(high+pad),width=620,height=195,left=52,right=594,top=24,bottom=145,count=Math.max(...series.map(g=>g.specimens.length)),x=i=>count===1?(left+right)/2:left+i/(count-1)*(right-left),y=v=>bottom-(v-min)/Math.max(1,max-min)*(bottom-top),ticks=[...new Set(Array.from({length:Math.min(6,count)},(_,i)=>count===1?0:Math.round(i*(count-1)/Math.max(1,Math.min(6,count)-1))))];return `<div class="lab-deviation-chart"><div class="lab-deviation-caption">Resistência dos CPs por idade de rompimento · MPa</div><svg role="img" aria-label="Resistências individuais dos CPs com uma linha para cada idade de rompimento" viewBox="0 0 ${width} ${height}">${[0,1/3,2/3,1].map(t=>{const value=min+(max-min)*t;return `<line x1="${left}" x2="${right}" y1="${y(value)}" y2="${y(value)}" stroke="#e5ebe7" stroke-width=".8"/><text x="${left-10}" y="${y(value)+3}" text-anchor="end" font-size="10" fill="#88978e">${labNum(value)}</text>`;}).join('')}${series.map((g,index)=>{const color=colors[index%colors.length],label=labNum(g.age)+' '+(g.unit==='hours'?'horas':'dias');return `<g data-deviation-age="${esc(label)}"><path d="${g.specimens.map((cp,i)=>(i?'L':'M')+x(i)+' '+y(cp.strength_mpa)).join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>${g.specimens.map((cp,i)=>`<circle cx="${x(i)}" cy="${y(cp.strength_mpa)}" r="3" fill="${color}"><title>${esc(cp.number)} · ${esc(label)} · ${labNum(cp.strength_mpa)} MPa · ${fmt(cp.broken_on)}${cp.broken_time?' '+cp.broken_time:''}</title></circle>${count<=6?`<text x="${x(i)}" y="${y(cp.strength_mpa)-8}" text-anchor="middle" fill="${color}" font-size="9">${labNum(cp.strength_mpa)}</text>`:''}`).join('')}</g>`;}).join('')}${ticks.map(i=>`<text x="${x(i)}" y="170" text-anchor="middle" fill="#88978e" font-size="10">CP ${i+1}</text>`).join('')}</svg><div class="lab-deviation-legend">${series.map((g,index)=>`<span><svg viewBox="0 0 22 8" aria-hidden="true"><path d="M1 4h20" stroke="${colors[index%colors.length]}" stroke-width="1.5"/><circle cx="11" cy="4" r="2" fill="${colors[index%colors.length]}"/></svg>${labNum(g.age)} ${g.unit==='hours'?'horas':'dias'}</span>`).join('')}</div></div>`;}
async function labSampleDeviation(id){try{const d=await api('/laboratory/samples/'+id+'/statistics');dialog('Desvio padrão · '+d.label,d.customer+' · '+d.work_name,`<div class="notice">Resultados separados pela idade real de rompimento. Desvio padrão amostral (n − 1), em MPa, com pelo menos dois CPs válidos por idade.</div><div class="table-wrap"><table><thead><tr><th>IDADE REAL</th><th>CPs VÁLIDOS</th><th>MÉDIA (MPa)</th><th>DESVIO PADRÃO (MPa)</th><th>MÍNIMA / MÁXIMA (MPa)</th></tr></thead><tbody>${d.groups.map(g=>`<tr><td><strong>${labNum(g.age)} ${g.unit==='hours'?'horas':'dias'}</strong></td><td>${g.n}</td><td>${labNum(g.mean)}</td><td><strong>${g.stddev===null?'Aguardando 2 resultados':labNum(g.stddev)}</strong></td><td>${labNum(g.minimum)} / ${labNum(g.maximum)}</td></tr>`).join('')||'<tr><td colspan="5">Ainda não há resultados válidos registrados nesta amostra.</td></tr>'}</tbody></table></div>${labDeviationChart(d.groups)}<div class="hint">FCK de referência: ${labNum(d.fck_mpa)} MPa · ${d.pending} CPs pendentes · ${d.invalidated} desconsiderados. O cálculo descreve a dispersão desta amostra; idades diferentes não são misturadas.</div>`);}catch(e){toast(e.message,true);}}
async function labAfterSave(message){const expanded=$$('.lab-set-card[open]').map(card=>card.dataset.labSet),scroll=window.scrollY;modal.close();await refresh();for(const id of expanded){const card=$('.lab-set-card[data-lab-set="'+id+'"]');if(card)card.open=true;}window.scrollTo({top:scroll});if(message)toast(message);}
async function labSampleDetail(id){try{const s=await api('/laboratory/samples/'+id);state.openLabSample=s;dialog(s.label||s.code,s.customer+' · '+s.work_name,`<div class="detail-grid"><div><small>Obra / endereço</small>${esc(s.work_name)}<br>${esc(s.address)}</div><div><small>NF / moldagem</small>${esc(s.invoice_no)} · ${fmt(s.molded_on)}</div><div><small>Concreto</small>FCK ${labNum(s.fck_mpa)} MPa · Slump na obra ${esc(s.slump||'—')} · Moldagem ${esc(s.molding_slump||'—')}</div><div><small>Temperaturas da moldagem</small>Concreto: ${labNum(s.concrete_temperature_c)} °C<br>Ambiente: ${labNum(s.ambient_temperature_c)} °C</div><div><small>Laboratorista responsável pela moldagem</small>${esc(s.molded_by_name||'Não informado')}${s.molded_by_role?'<br><small>'+esc(roleNames[s.molded_by_role]||s.molded_by_role)+'</small>':''}</div><div><small>Entrega</small>${esc(s.cb_code)} · ${esc(s.cb_plate)}<br>${esc(s.driver_name)}</div><div><small>Adição de água</small>${s.water_added?labNum(s.water_liters)+' L':'Não'}</div><div><small>Estabilizador de hidratação</small>${s.stabilizer_added?labNum(s.stabilizer_liters)+' L':'Não'}</div><div><small>Vencimento</small>${s.expired===1?'Sim'+(s.expiry_excess_hours!==null&&s.expiry_excess_hours!==undefined?' · '+labNum(s.expiry_excess_hours)+' h após o vencimento':' · horas não informadas'):s.expired===0?'Não':'Não informado'}</div><div><small>Observações</small>${esc(s.notes||'—')}</div></div><div class="actions"><button id="lab-sample-edit">Editar amostra</button>${s.set_type?'':'<button id="lab-add-specimens">Adicionar CPs</button>'}</div>${labSpecimensTable(s.specimens)}<details><summary>Histórico das alterações</summary>${s.events.map(e=>`<article class="history-event"><strong>${esc(e.action)} · ${esc(e.actor_name)}</strong><small>${new Date(e.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small><p>${esc(e.reason)}</p></article>`).join('')}</details>`);$('#lab-sample-edit',modal).onclick=()=>labSampleForm(s);if($('#lab-add-specimens',modal))$('#lab-add-specimens',modal).onclick=()=>labAddSpecimens(s);bindLabRowActions(modal,s.specimens);}catch(e){toast(e.message,true);}}
const labCpRow=(number='',age=28)=>`<div class="form-grid lab-cp-input"><label>Número do CP *<input data-cp-number required maxlength="60" value="${esc(number)}"></label><label>Idade prevista (dias) *<input data-cp-age type="number" required min="1" max="3650" step="1" value="${age}"></label><button type="button" data-remove-lab-cp>Remover CP</button></div>`;
function bindLabCpInputs(){const host=$('#lab-cp-inputs',modal);$('#lab-add-cp-row',modal).onclick=()=>{if($$('.lab-cp-input',host).length<100)host.insertAdjacentHTML('beforeend',labCpRow());};host.onclick=e=>{if(e.target.closest('[data-remove-lab-cp]')){if($$('.lab-cp-input',host).length===1){toast('Mantenha pelo menos um CP.',true);return;}e.target.closest('.lab-cp-input').remove();}};}
const labCpValues=()=>$$('.lab-cp-input',modal).map(row=>({number:$('[data-cp-number]',row).value,target_age:$('[data-cp-age]',row).value}));
function labStaffAvatar(person,size=''){const initials=String(person?.name||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('');return person?.photo_version?`<img class="profile-avatar ${size}" src="/api/laboratory/staff-photos/${person.id}?v=${encodeURIComponent(person.photo_version)}" alt="Foto de ${esc(person.name)}">`:`<span class="avatar profile-avatar ${size}" aria-hidden="true">${esc(initials)}</span>`;}
function labMolderPicker(s,staff){const selected=staff.find(p=>p.id===s?.molded_by_user_id),legacy=!selected&&s?.molded_by_name?{name:s.molded_by_name,role:s.molded_by_role}:null,person=selected||legacy;return `<div class="span-2 lab-molder-picker"><label id="lab-molder-label">Laboratorista responsável pela moldagem *</label><input type="hidden" name="molded_by_user_id" value="${selected?.id||''}"><button class="lab-molder-toggle" id="lab-molder-toggle" type="button" aria-haspopup="listbox" aria-expanded="false" aria-labelledby="lab-molder-label lab-molder-selection"><span id="lab-molder-selection">${person?labStaffAvatar(person)+`<span><strong>${esc(person.name)}</strong><small>${esc(roleNames[person.role]||'Registro anterior')}</small></span>`:'Selecione o laboratorista'}</span>${icon('right')}</button><div id="lab-molder-options" class="lab-molder-options" role="listbox" aria-labelledby="lab-molder-label" hidden>${staff.map(p=>`<button type="button" role="option" aria-selected="${p.id===selected?.id}" data-lab-molder="${p.id}">${labStaffAvatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(roleNames[p.role])}</small></span></button>`).join('')||'<p>Nenhum Laboratorista ou Auxiliar de Laboratório aprovado. O Programador pode cadastrá-los em Configurações.</p>'}</div></div>`;}
function bindLabMolderPicker(staff){const button=$('#lab-molder-toggle',modal),options=$('#lab-molder-options',modal),picker=button.closest('.lab-molder-picker');const open=value=>{options.hidden=!value;button.setAttribute('aria-expanded',String(value));};button.onclick=()=>open(options.hidden);button.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();open(true);$('[role=option]',options)?.focus();}if(e.key==='Escape')open(false);};$$('[data-lab-molder]',options).forEach((option,index,all)=>{option.onclick=()=>{const person=staff.find(p=>p.id===Number(option.dataset.labMolder));$('[name=molded_by_user_id]',modal).value=person.id;$('#lab-molder-selection',modal).innerHTML=labStaffAvatar(person)+`<span><strong>${esc(person.name)}</strong><small>${esc(roleNames[person.role])}</small></span>`;all.forEach(el=>el.setAttribute('aria-selected',String(el===option)));open(false);button.focus();};option.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();all[(index+(e.key==='ArrowDown'?1:all.length-1))%all.length].focus();}if(e.key==='Escape'){open(false);button.focus();}};});button.closest('form').addEventListener('click',e=>{if(!picker.contains(e.target))open(false);});}
