 bindLabMolderPicker(meta.staff||[]);
 const expiryHours=$('[name=expiry_excess_hours]',modal),expiryLabel=$('#lab-expiry-hours',modal);const updateExpiry=()=>{const yes=$('[name=expired]:checked',modal)?.value==='1';expiryLabel.hidden=!yes;expiryHours.disabled=!yes;expiryHours.required=yes;};$$('[name=expired]',modal).forEach(input=>input.onchange=updateExpiry);updateExpiry();
