function labDocumentsPage(){return heading('Laudos por cliente','Escolha o cliente, o mês, as obras e as notas fiscais para reunir os CPs.',`<button class="primary" id="lab-new-document">Gerar laudo por cliente</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>LAUDO</th><th>CLIENTE</th><th>GERADO EM</th><th></th></tr></thead><tbody>${(state.labDocuments||[]).map(d=>`<tr><td>LAB-${String(d.id).padStart(6,'0')}</td><td>${esc(d.customer)}</td><td>${new Date(d.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</td><td><button data-lab-document="${d.id}">Abrir / baixar PDF</button></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">Nenhum laudo gerado.</div></td></tr>'}</tbody></table></div></section>`;}
async function labDocumentForm(){try{const options=await api('/laboratory/document-options'),clients=[...new Map(options.map(o=>[o.client_key,o])).values()],configuration=state.labMeta.policy;dialog('Gerar laudo por cliente','Selecione o cliente, o mês e as notas fiscais para reunir os CPs.',`<form id="lab-document-form"><div class="form-grid"><label>Cliente *<select name="client_key" required id="lab-document-client"><option value="">Selecione o cliente</option>${clients.map(c=>`<option value="${c.client_key}">${esc(c.customer)} · ${esc(c.customer_code||'Sem código')}</option>`).join('')}</select></label><label>Mês de moldagem *<input name="month" id="lab-document-month" type="month" required value="${today().slice(0,7)}"></label><div class="span-2"><strong>Obras do mês</strong><div id="lab-document-works" class="lab-check-list"></div></div><div class="span-2 lab-document-invoices"><strong>Notas fiscais e datas de moldagem</strong><div id="lab-document-invoices"><div class="empty">Selecione o cliente e o mês para ver as notas fiscais.</div></div></div><label class="span-2">Observações do laudo<textarea name="notes" maxlength="4000"></textarea></label><label class="span-2 lab-checkbox"><input name="confirmed" type="checkbox">Dados conferidos para emissão e assinatura</label></div><div class="hint">O documento é preparado para conferência e assinatura do responsável técnico. Não inclui a informação de vencimento do concreto.</div>${footer('Gerar laudo')}</form>`,async(data,form)=>{const works=$$('[name=works]:checked',form).map(i=>i.value),sample_ids=$$('[name=sample_ids]:checked',form).map(i=>Number(i.value));if(!works.length||!sample_ids.length)throw Error('Selecione pelo menos uma obra e uma nota fiscal.');const d=await api('/laboratory/documents',{method:'POST',body:JSON.stringify({...data,confirmed:data.confirmed==='on',works,sample_ids})});modal.close();state.selectedLabDocumentId=d.id;state.page='labDocument';await refresh();});const form=$('#lab-document-form',modal),host=$('#lab-document-invoices',form),workHost=$('#lab-document-works',form);let generation=0,records=[],selected=new Set();const renderInvoices=()=>{const works=new Set($$('[name=works]:checked',form).map(i=>i.value)),rows=records.filter(r=>works.has(r.work_key));host.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th></th><th>NOTA FISCAL</th><th>MOLDAGEM</th><th>OBRA / CB / ETIQUETA</th><th>CPs</th></tr></thead><tbody>${rows.map(r=>`<tr><td><input type="checkbox" name="sample_ids" value="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="Incluir NF ${esc(r.invoice_no)} de ${fmt(r.molded_on)} · ${esc(r.label||r.code)}"></td><td><strong>${esc(r.invoice_no)}</strong></td><td>${fmt(r.molded_on)}</td><td>${esc(r.work_name)}<small>${esc(r.cb_code)} · ${esc(r.label||r.code)}</small></td><td>${r.tested_count}/${r.cp_count}<small>com resultado</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma nota fiscal para o mês e obras selecionados.</div>';$$('[name=sample_ids]',host).forEach(input=>input.onchange=()=>{if(input.checked)selected.add(Number(input.value));else selected.delete(Number(input.value));});};const loadInvoices=async()=>{const current=++generation,client=$('#lab-document-client',form).value,month=$('#lab-document-month',form).value;records=[];selected.clear();workHost.innerHTML='';if(!client||!month){host.innerHTML='<div class="empty">Selecione o cliente e o mês para ver as notas fiscais.</div>';return;}const button=$('[type=submit]',form);button.disabled=true;host.innerHTML='<div class="empty">Consultando notas fiscais…</div>';try{const rows=await api('/laboratory/document-samples?'+new URLSearchParams({client,month}));if(current!==generation||!form.isConnected)return;records=rows;selected=new Set(rows.map(r=>r.id));const works=[...new Map(rows.map(r=>[r.work_key,r])).values()];workHost.innerHTML=works.map(w=>`<label class="lab-checkbox"><input name="works" type="checkbox" value="${w.work_key}" checked>${esc(w.work_name)} · ${esc(w.address)}</label>`).join('');$$('[name=works]',workHost).forEach(input=>input.onchange=renderInvoices);renderInvoices();}catch(e){if(current===generation&&form.isConnected){records=[];host.innerHTML='<div class="empty">Não foi possível consultar as notas fiscais. Selecione o mês novamente.</div>';toast(e.message,true);}}finally{if(current===generation&&form.isConnected)button.disabled=false;}};$('#lab-document-client',form).onchange=loadInvoices;$('#lab-document-month',form).onchange=loadInvoices;}catch(e){toast(e.message,true);}}

function labDocumentResistanceTable(rows){const samples=[...new Set(rows.map(cp=>cp.sample_id))];return samples.map(id=>{const cps=rows.filter(cp=>cp.sample_id===id),s=cps[0],groups=new Map();for(const cp of cps){const age=cp.broken_on?(cp.target_age===.5?cp.actual_age_hours:cp.actual_age):cp.target_age,key=JSON.stringify([cp.broken_on||'',age,cp.target_age===.5]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(cp);}const ordered=[...groups.values()].sort((a,b)=>(a[0].target_age-b[0].target_age)||(a[0].broken_on||'').localeCompare(b[0].broken_on||'')),count=Math.max(2,...ordered.map(g=>g.length));return `<section class="lab-resistance-sample"><div class="detail-grid lab-document-meta"><div><small>Etiqueta / nota fiscal</small><strong>${esc(s.label||s.sample_code)}</strong> · NF ${esc(s.invoice_no)}</div><div><small>Data de concretagem / moldagem</small>${fmt(s.molded_on)}</div><div><small>FCK de referência</small>${labNum(s.fck_mpa)} MPa</div><div><small>Caminhão / motorista</small>${esc(s.cb_code)} · ${esc(s.cb_plate)}<br>${esc(s.driver_name)}</div><div><small>Slump na obra / moldagem</small>${esc(s.slump||'Não informado')} / ${esc(s.molding_slump||'Não informado')}</div><div><small>Adições</small>Água: ${s.water_added?labNum(s.water_liters)+' L':'sem adição informada'}<br>Estabilizador: ${s.stabilizer_added?labNum(s.stabilizer_liters)+' L':'sem adição informada'}</div></div><div class="table-wrap"><table class="lab-resistance-table"><thead><tr><th>Data de rompimento</th><th>Idade</th>${Array.from({length:count},(_,i)=>`<th>Fc Resistência (MPa) · CP${i+1}</th>`).join('')}</tr></thead><tbody>${ordered.map(group=>{const cp=group[0],age=cp.broken_on?(cp.target_age===.5?labNum(cp.actual_age_hours)+' horas':labNum(cp.actual_age)+' dias'):(cp.target_age===.5?'12 horas':labNum(cp.target_age)+' dias');return `<tr><td>${cp.broken_on?fmt(cp.broken_on):'Pendente'}${!cp.broken_on?'<small>Previsto: '+fmt(cp.planned_on)+'</small>':''}</td><td>${age}</td>${Array.from({length:count},(_,i)=>{const item=group[i];return `<td>${item?`<strong>${item.strength_mpa===null?'Pendente':labNum(item.strength_mpa,2)}</strong><small>${esc(item.number)}</small>`:'—'}</td>`;}).join('')}</tr>`;}).join('')}</tbody></table></div></section>`;}).join('');}
function labDocumentPage(){const d=state.labDocument;if(!d)return '<div class="empty">Laudo não encontrado.</div>';const linked=state.page==='ticketLabDocument';return heading('Laudo LAB-'+String(d.id).padStart(6,'0'),d.customer,`<button id="${linked?'lab-linked-back':'lab-documents-back'}">Voltar</button>${!linked&&canLab()?'<button id="lab-attach-document">Adicionar ao chamado</button>':''}<button id="print">Imprimir / salvar PDF</button>`)+reportHeader('Laudo técnico de avaliação do desempenho do concreto · LAB-'+String(d.id).padStart(6,'0'),d.customer)+`<div class="lab-document-status">${d.status==='para_assinatura'?'Emitido para assinatura do responsável técnico':'RASCUNHO · Para conferência e assinatura do responsável técnico'}</div><section class="panel"><div class="detail-grid lab-document-meta"><div><small>Cliente / código</small><strong>${esc(d.customer)}</strong><br>${esc(d.customer_code||'Não informado')}</div><div><small>Período de moldagem</small>${d.all?'Todo o histórico das obras selecionadas':fmt(d.from)+' a '+fmt(d.to)}</div><div><small>Responsável técnico</small>${esc(d.responsible_name||'A preencher')}</div><div><small>CREA</small>${esc(d.crea||'A preencher')}</div><div><small>Norma / método informado</small>${esc(d.test_standard||'A preencher pelo responsável técnico')}</div><div><small>Preparado por</small>${esc(d.prepared_by_name)}<br>${new Date(d.prepared_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</div></div></section>${[...new Set(d.rows.map(cp=>cp.work_key))].map(key=>{const rows=d.rows.filter(cp=>cp.work_key===key);return `<section class="panel lab-document-work"><div class="panel-header"><div><h2>${esc(rows[0].work_name)}</h2><small>${esc(rows[0].address)}</small></div></div>${labDocumentResistanceTable(rows)}</section>`;}).join('')}<section class="panel lab-document-notes"><p class="lab-document-standards">Referências normativas da ABNT: NBR 7212 — Concreto dosado em central; NBR 5738 — Moldagem e cura de corpos de prova; NBR 5739 — Ensaio de compressão de corpos de prova cilíndricos; NBR 12654 — Controle tecnológico de materiais componentes do concreto; NM 33 — Amostragem de concreto fresco; NM 67 — Determinação da consistência pelo abatimento do tronco de cone.</p><p>${esc(d.notes||'Sem observações adicionais.')}</p><p>Resultados conforme registros do laboratório. Comparações com o FCK informado são descritivas; a avaliação de aceitação do concreto cabe ao responsável técnico.</p><p>Desvio padrão amostral dos CPs aos 28 dias: ${labNum(d.statistics.stddev,3)} MPa · n = ${d.statistics.n}. Não calculado quando há menos de dois resultados.</p><div class="lab-signature">${esc(d.responsible_name||'Responsável técnico')} · CREA ${esc(d.crea||'________________')}<br>Conferência e assinatura</div></section>`;}
