async function labAttachFromTicket(ticket){try{const docs=await api('/laboratory/documents');if(!docs.length)throw Error('Gere o laudo no Laboratório antes de adicioná-lo.');dialog('Escolher laudo do laboratório',ticket.customer,`<form><label>Laudo *<select name="document_id" required><option value="">Selecione</option>${docs.map(d=>`<option value="${d.id}">LAB-${String(d.id).padStart(6,'0')} · ${esc(d.customer)}</option>`).join('')}</select></label>${footer('Continuar')}</form>`,async data=>labAttachDocument(Number(data.document_id),ticket));}catch(e){toast(e.message,true);}}
