let labChartTooltipEvents;
function bindLabMoistureChart(){labChartTooltipEvents?.abort();$('#lab-moisture-tooltip')?.remove();const chart=$('.lab-moisture-chart');if(!chart)return;const controller=new AbortController();labChartTooltipEvents=controller;const tip=document.createElement('div');tip.id='lab-moisture-tooltip';tip.className='lab-moisture-tooltip no-print';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);const hide=()=>{tip.hidden=true;$$('[data-lab-moisture-point]').forEach(p=>p.removeAttribute('aria-describedby'));};const show=point=>{const row=state.labMoisture.find(m=>m.id===Number(point.dataset.labMoisturePoint));if(!row)return;tip.innerHTML=`<header><strong>${esc(labStockLabel(row))}</strong><span>${labNum(row.moisture_percent)}%</span></header><div class="lab-tooltip-date">${fmt(row.measured_at.slice(0,10))} · ${esc(row.measured_at.slice(11))}</div><dl><div><dt>Peso coletado</dt><dd>${row.wet_mass_g===null?'Não informado':labNum(row.wet_mass_g)+' g'}</dd></div><div><dt>Peso seco</dt><dd>${row.dry_mass_g===null?'Não informado':labNum(row.dry_mass_g)+' g'}</dd></div><div><dt>Diferença</dt><dd>${row.difference_pp===null?'Primeiro registro':(row.difference_pp>0?'+':'')+labNum(row.difference_pp)+' p.p.'}</dd></div><div><dt>Tempo na coleta</dt><dd>${labWeatherLabel(row.weather)}</dd></div><div><dt>Registrado por</dt><dd>${esc(row.author_name)}</dd></div></dl>${row.notes?`<p>${esc(row.notes)}</p>`:''}`;tip.hidden=false;point.setAttribute('aria-describedby',tip.id);const rect=point.getBoundingClientRect(),width=tip.offsetWidth,height=tip.offsetHeight;tip.style.left=Math.max(10,Math.min(innerWidth-width-10,rect.left+rect.width/2-width/2))+'px';tip.style.top=Math.max(10,Math.min(innerHeight-height-10,rect.top-height-12>=10?rect.top-height-12:rect.bottom+12))+'px';};$$('[data-lab-moisture-point]',chart).forEach(point=>{point.onpointerenter=()=>show(point);point.onpointerleave=hide;point.onfocus=()=>show(point);point.onblur=hide;point.onclick=e=>{e.stopPropagation();show(point);};point.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();show(point);}if(e.key==='Escape')hide();};});document.addEventListener('click',e=>{if(!e.target.closest('[data-lab-moisture-point]'))hide();},{signal:controller.signal});document.addEventListener('scroll',()=>{const point=$('[data-lab-moisture-point][aria-describedby]');if(point?.matches(':hover,:focus'))show(point);else hide();},{capture:true,signal:controller.signal});window.addEventListener('resize',hide,{signal:controller.signal});document.addEventListener('keydown',e=>{if(e.key==='Escape')hide();},{signal:controller.signal});}

function labMoisturePage(){const f=state.labMoistureFilters,rows=(state.labMoisture||[]).filter(r=>(!f.weather||r.weather===f.weather)&&(!f.stock||labStockLabel(r)===f.stock)),values=rows.map(r=>r.moisture_percent),average=values.length?values.reduce((a,b)=>a+b,0)/values.length:null,stocks=[...new Set((state.labMoisture||[]).map(labStockLabel))];return heading('Umidade da areia','Medições por estoque, datas e horários, com evolução semanal.',`<button id="print">Imprimir / salvar PDF</button><button class="primary" id="lab-moisture-new">Registrar umidade</button>`)+reportHeader('Controle de umidade da areia',fmt(f.from)+' a '+fmt(f.to))+labRangeForm('lab-moisture-filter',f,`<label>Semana de referência<input id="lab-moisture-week" type="date" value="${f.from}"></label><label>Tempo na coleta<select name="weather"><option value="">Todos</option>${Object.entries(labCollectionWeather).map(([v,w])=>`<option value="${v}" ${f.weather===v?'selected':''}>${w.label}</option>`).join('')}</select></label><label>Estoque<select name="stock"><option value="">Todos</option>${stocks.map(v=>`<option value="${esc(v)}" ${f.stock===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`)+`<div class="stats">${stat('Medições',rows.length,'registros','No período e filtros selecionados','droplet')}${stat('Umidade média',labNum(average),'%','Média das medições selecionadas','chart')}${stat('Mínima / máxima',values.length?labNum(Math.min(...values))+' / '+labNum(Math.max(...values)):'—','%','Consulte cada estoque separadamente','chart')}</div><section id="lab-weather" class="panel no-print"><div class="panel-header"><h2>Previsão do tempo · Cascavel – PR</h2></div><div class="empty">Consultando a previsão do INMET…</div></section><section class="panel"><div class="panel-header"><h2>Evolução da umidade medida (%)</h2><small>Linhas separadas por estoque</small></div>${labMoistureChart(rows)}</section><section class="panel"><div class="panel-header"><h2>Histórico de medições</h2></div><div class="table-wrap"><table><thead><tr><th>DATA / HORÁRIO</th><th>ESTOQUE / TEMPO NA COLETA</th><th>PESO COLETADO / SECO</th><th>UMIDADE</th><th>DIFERENÇA</th><th>REGISTRADO POR / OBSERVAÇÃO</th><th class="no-print">AÇÕES</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${fmt(m.measured_at.slice(0,10))}<small>${m.measured_at.slice(11)}</small></td><td>${esc(labStockLabel(m))}<small>${labWeatherLabel(m.weather)}</small></td><td>${m.wet_mass_g===null||m.wet_mass_g===undefined?'—<small>Registro anterior sem pesagem</small>':labNum(m.wet_mass_g)+' g<small>Seco: '+labNum(m.dry_mass_g)+' g</small>'}</td><td><strong>${labNum(m.moisture_percent)}%</strong></td><td>${m.difference_pp===null?'Primeiro registro':(m.difference_pp>0?'+':'')+labNum(m.difference_pp)+' p.p.'}</td><td>${esc(m.author_name)}<small>${esc(m.notes)}</small></td><td class="no-print"><div class="lab-moisture-actions"><button class="icon-only" data-lab-moisture-edit="${m.id}" aria-label="Editar medição" title="Editar medição">${icon('edit')}</button><button class="icon-only lab-moisture-delete" data-lab-moisture-delete="${m.id}" aria-label="Excluir medição" title="Excluir medição">${icon('trash')}</button></div></td></tr>`).join('')||'<tr><td colspan="7">Sem medições.</td></tr>'}</tbody></table></div><div class="hint">Diferença em pontos percentuais em relação à medição anterior do mesmo estoque dentro do período. A previsão é contexto e não substitui a medição da umidade da areia.</div></section>`;}
async function labWeather(){const host=$('#lab-weather');if(!host)return;try{const weather=await api('/laboratory/weather');if(!host.isConnected)return;host.innerHTML='<div class="panel-header"><h2>Previsão do tempo · '+esc(weather.location)+'</h2><a href="https://portal.inmet.gov.br/" target="_blank" rel="noopener noreferrer">Fonte: INMET</a></div>'+(weather.available?`<div class="lab-weather-days">${weather.days.map(d=>`<div><strong>${fmt(d.date,{weekday:'short',day:'numeric',month:'short'})}</strong><p>${esc(d.description)}</p><small>${labNum(d.min)}°C / ${labNum(d.max)}°C</small></div>`).join('')}</div><div class="hint">Atualizada em ${new Date(weather.updated_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}. Dados do serviço externo; previsão sujeita a atualização.</div>`:'<div class="empty">Não foi possível obter a previsão agora. As medições de umidade continuam disponíveis normalmente.</div>');}catch{if(host.isConnected)host.innerHTML='<div class="empty">Previsão indisponível. Consulte o INMET; o controle de umidade continua funcionando.</div>';}}
const labCollectionWeather={sol:{icon:'sun',label:'Sol'},nublado:{icon:'cloud',label:'Nublado'},chuva:{icon:'rain',label:'Chuva'}};
function labWeatherLabel(value){const w=labCollectionWeather[value];return w?`<span class="lab-weather-observed">${icon(w.icon)}${w.label}</span>`:'Tempo não informado';}
function labMoistureForm(m=null){dialog(m?'Editar medição de umidade':'Registrar umidade da areia','Medição de laboratório · horários de Cascavel – PR.',`<form><div class="form-grid"><label>Data e horário da medição *<input name="measured_at" type="datetime-local" required value="${labNow()}"></label><label>Estoque / local *<select name="stock" required aria-label="Estoque / local *"><option value="">Selecione a baia</option><option value="Baia 01">Baia 01</option><option value="Baia 02">Baia 02</option></select></label><fieldset class="span-2 lab-collection-weather"><legend>Tempo no momento da coleta *</legend><div>${Object.entries(labCollectionWeather).map(([key,w])=>`<label><input type="radio" name="weather" value="${key}" required><span>${icon(w.icon)}${w.label}</span></label>`).join('')}</div></fieldset><label>Peso da areia coletada (g) *<input name="wet_mass_g" type="number" min="0.001" step="any" required inputmode="decimal"></label><label>Peso da areia seca (g) *<input name="dry_mass_g" type="number" min="0.001" step="any" required inputmode="decimal"></label><div class="span-2 lab-moisture-result" role="status" aria-live="polite"><span>Umidade calculada</span><strong id="lab-calculated-moisture">—</strong><small id="lab-mass-help">Informe os pesos da areia, sem o recipiente.</small></div><label class="span-2">Observações<textarea name="notes" maxlength="2000"></textarea></label></div>${footer(m?'Salvar alterações':'Salvar medição')}</form>`,async data=>{await api('/laboratory/moisture'+(m?'/'+m.id:''),{method:m?'PATCH':'POST',body:JSON.stringify({...data,...(m?{expected_revision:m.revision}:{})})});modal.close();await refresh();});const wet=$('[name=wet_mass_g]',modal),dry=$('[name=dry_mass_g]',modal);const update=()=>{const w=Number(wet.value),d=Number(dry.value),valid=wet.value!==''&&dry.value!==''&&Number.isFinite(w)&&Number.isFinite(d)&&d>0&&w>=d;dry.setCustomValidity(dry.value!==''&&(d<=0||(wet.value!==''&&d>w))?'O peso seco deve ser maior que zero e não pode superar o peso coletado.':'');$('#lab-calculated-moisture',modal).textContent=valid?((w-d)/d*100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+'%':'—';$('#lab-mass-help',modal).textContent=valid?'(Peso coletado − peso seco) ÷ peso seco × 100 · pesos sem o recipiente.':dry.validationMessage||'Informe os pesos da areia, sem o recipiente.';};wet.oninput=update;dry.oninput=update;if(m){for(const key of ['measured_at','stock','wet_mass_g','dry_mass_g','notes']){const field=$('[name='+key+']',modal);if(key==='stock'&&m.stock&&!['Baia 01','Baia 02'].includes(m.stock))field.add(new Option(m.stock,m.stock));field.value=m[key]??'';}const weather=$('[name=weather][value="'+m.weather+'"]',modal);if(weather)weather.checked=true;update();}}
function labDeleteMoisture(m){dialog('Excluir medição','Esta medição será removida do histórico e dos gráficos.',`<form><div class="notice">${esc(m.stock)} · ${fmt(m.measured_at.slice(0,10))} às ${esc(m.measured_at.slice(11))} · ${labNum(m.moisture_percent)}%</div>${footer('Excluir medição')}</form>`,async()=>{await api('/laboratory/moisture/'+m.id,{method:'DELETE',body:JSON.stringify({expected_revision:m.revision})});modal.close();await refresh();});}

function labPolicyForm(){const p=state.labMeta.policy;dialog('Parâmetros do laboratório','A meta de ocorrências considera cada CP individual aos 28 dias.',`<form><div class="form-grid"><label class="span-2">Norma / método de ensaio informado<input name="test_standard" maxlength="300" value="${esc(p.test_standard)}"></label></div><div class="hint">O vencimento é informado como Sim ou Não no cadastro da amostra e não aparece nos laudos.</div>${footer('Salvar parâmetros')}</form>`,async data=>{await api('/laboratory/policy',{method:'PATCH',body:JSON.stringify(data)});modal.close();await refresh();});}
function bindLaboratory(){
 $$('.lab-occurrence-frame').forEach(frame=>{frame.style.minWidth=frame.dataset.chartWidth+'px';const people=$('.lab-molder-chart-people',frame);if(people){people.style.gridTemplateColumns='repeat('+people.dataset.count+',minmax(0,1fr))';people.style.marginLeft=people.dataset.left+'%';people.style.marginRight=people.dataset.right+'%';}});
 if($('#lab-print-sheet'))$('#lab-print-sheet').onclick=async()=>{state.page='labMoldingSheet';await refresh();await printReport();};if($('#lab-sheet-back'))$('#lab-sheet-back').onclick=()=>{state.page='laboratory';refresh();};
 bindLabMoistureChart();
 if($('#lab-new-sample'))$('#lab-new-sample').onclick=()=>labSampleForm();if($('#lab-driver-new'))$('#lab-driver-new').onclick=()=>dialog('Cadastrar motorista','Nome para rastrear a entrega e os indicadores.',`<form><label>Nome do motorista *<input name="name" required maxlength="200"></label>${footer('Cadastrar motorista')}</form>`,async data=>{await api('/laboratory/drivers',{method:'POST',body:JSON.stringify(data)});modal.close();await refresh();});
 if($('#lab-policy'))$('#lab-policy').onclick=labPolicyForm;if($('#lab-new-document'))$('#lab-new-document').onclick=labDocumentForm;if($('#lab-moisture-new'))$('#lab-moisture-new').onclick=()=>labMoistureForm();
 $$('[data-lab-moisture-edit]').forEach(b=>b.onclick=()=>labMoistureForm(state.labMoisture.find(m=>m.id===Number(b.dataset.labMoistureEdit))));$$('[data-lab-moisture-delete]').forEach(b=>b.onclick=()=>labDeleteMoisture(state.labMoisture.find(m=>m.id===Number(b.dataset.labMoistureDelete))));
 bindLabRowActions();$$('[data-lab-document]').forEach(b=>b.onclick=()=>{state.selectedLabDocumentId=Number(b.dataset.labDocument);state.page='labDocument';refresh();});
 if($('#lab-attach-document'))$('#lab-attach-document').onclick=()=>labAttachDocument(state.selectedLabDocumentId);if($('#lab-documents-back'))$('#lab-documents-back').onclick=()=>{state.page='labDocuments';refresh();};if($('#lab-linked-back'))$('#lab-linked-back').onclick=()=>{state.page='ticketView';refresh();};
 for(const [id,key] of [['lab-sample-filter','labSampleFilters'],['lab-specimen-filter','labSpecimenFilters'],['lab-report-filter','labReportFilters'],['lab-moisture-filter','labMoistureFilters']]){const form=$('#'+id);if(form)form.onsubmit=e=>{e.preventDefault();state[key]=key==='labReportFilters'?Object.fromEntries(new FormData(form)):{...state[key],...Object.fromEntries(new FormData(form))};if(form.elements.all)state[key].all=form.elements.all.checked;refresh();};}
 const sampleFilter=$('#lab-sample-filter');if(sampleFilter){const all=sampleFilter.elements.all,update=()=>{sampleFilter.elements.from.disabled=all.checked;sampleFilter.elements.to.disabled=all.checked;};all.onchange=update;update();}
 if($('#lab-report-filter [name=client]'))$('#lab-report-filter [name=client]').onchange=()=>{const form=$('#lab-report-filter'),client=$('[name=client]',form).value;$('[name=work]',form).innerHTML='<option value="">Todas</option>'+state.labMeta.works.filter(w=>!client||w.client_key===client).map(w=>`<option value="${w.work_key}">${esc(w.work_name)} · ${esc(w.address)}</option>`).join('');};
 if($('#lab-moisture-week'))$('#lab-moisture-week').onchange=e=>{const day=e.target.value;if(!day)return;const offset=(new Date(day+'T12:00:00').getDay()+6)%7,from=shift(day,-offset);const form=$('#lab-moisture-filter');$('[name=from]',form).value=from;$('[name=to]',form).value=shift(from,6);};
 if(state.page==='labMoisture')labWeather();
}
